import csv
import sys
from statistics import mean, median

def is_number(s):
    try:
        float(s)
        return True
    except ValueError:
        return False

def main(filename):
    with open(filename, newline='') as csvfile:
        reader = csv.DictReader(csvfile)
        data = list(reader)

        if not data:
            print("Empty CSV file")
            return

        # Filter numeric columns
        numeric_columns = []
        for col in data[0].keys():
            # Check first non-empty value if numeric
            for row in data:
                if row[col] != '':
                    if is_number(row[col]):
                        numeric_columns.append(col)
                    break

        if not numeric_columns:
            print("No numeric columns found.")
            return

        # Collect column data
        col_values = {col: [] for col in numeric_columns}
        for row in data:
            for col in numeric_columns:
                if row[col] != '':
                    col_values[col].append(float(row[col]))

        # Print mean and median
        for col in numeric_columns:
            m = mean(col_values[col])
            med = median(col_values[col])
            print(f"{col}: Mean = {m}, Median = {med}")

if __name__ == '__main__':
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} <csvfile>")
    else:
        main(sys.argv[1])
EOF

